$plugins = @(
  @{ Id='obsidian-git'; Repo='Vinzent03/obsidian-git'; Files=@('main.js','manifest.json','styles.css') },
  @{ Id='templater-obsidian'; Repo='SilentVoid13/Templater'; Files=@('main.js','manifest.json','styles.css') },
  @{ Id='tag-wrangler'; Repo='pjeby/tag-wrangler'; Files=@('main.js','manifest.json') },
  @{ Id='obsidian-shellcommands'; Repo='Taitava/obsidian-shellcommands'; Files=@('main.js','manifest.json','styles.css') }
)
foreach ($plugin in $plugins) {
  $release = Invoke-RestMethod -Uri "https://api.github.com/repos/$($plugin.Repo)/releases/latest" -Headers @{ 'User-Agent'='Codex' }
  $dir = Join-Path '.obsidian\plugins' $plugin.Id
  New-Item -ItemType Directory -Force -Path $dir | Out-Null
  foreach ($file in $plugin.Files) {
    $asset = $release.assets | Where-Object { $_.name -eq $file } | Select-Object -First 1
    Invoke-WebRequest -Uri $asset.browser_download_url -OutFile (Join-Path $dir $file) -Headers @{ 'User-Agent'='Codex' }
  }
}
Get-ChildItem -Force -Name -LiteralPath '.obsidian\plugins' | Sort-Object

